// Smart fuzzy lookup: normalizes both the app's PDF name and the Drive key
// to handle mismatches like extra spaces, underscores, trailing .pdf, etc.
function normalize(str) {
  return str
    .replace(/\.pdf$/i, '')       // Remove trailing .pdf
    .replace(/^_+/, '')           // Remove leading underscores  
    .replace(/[_\-–]+/g, ' ')    // Replace underscores/dashes with spaces
    .replace(/\s+/g, ' ')        // Collapse multiple spaces
    .trim()
    .toLowerCase();
}

// Pre-build a normalized lookup index
const NORMALIZED_MAP = {};
for (const [key, id] of Object.entries(DRIVE_MAP)) {
  NORMALIZED_MAP[normalize(key)] = id;
}

/**
 * Given a PDF display name from data.js, find its Google Drive File ID.
 * Uses fuzzy normalization to handle naming inconsistencies.
 */
export function getDriveId(pdfName) {
  // Try exact match first
  if (DRIVE_MAP[pdfName]) return DRIVE_MAP[pdfName];
  
  // Try normalized fuzzy match
  const normalized = normalize(pdfName);
  if (NORMALIZED_MAP[normalized]) return NORMALIZED_MAP[normalized];
  
  // Try partial match (find a key that contains the normalized name)
  for (const [normKey, id] of Object.entries(NORMALIZED_MAP)) {
    if (normKey.includes(normalized) || normalized.includes(normKey)) {
      return id;
    }
  }
  
  return null;
}
